//! Source and MIT license: `Assets/Fluent/NOTICE.md` and `Assets/Fluent/LICENSE`.
//! Geometry is parsed once per UI thread and shared; foreground is inherited from
//! the current control theme, so custom accents and light/dark variants stay native.
use ferroui_base::media::{Geometry, RotateTransform};
use ferroui_base::Ref;
use ferroui_controls::automation::{AccessibilityView, AutomationProperties};
use ferroui_controls::PathIcon;
use std::cell::RefCell;
use std::collections::BTreeMap;

ferroui_base::ferro_thread_local! {
    static GEOMETRIES: RefCell<BTreeMap<&'static str, Ref<Geometry>>> = RefCell::new(BTreeMap::new());
}

pub(crate) fn icon(name: &str) -> Ref<PathIcon> {
    let data = path_data(name);
    let geometry = GEOMETRIES.with(|cache| {
        let mut cache = cache.borrow_mut();
        cache
            .entry(data)
            .or_insert_with(|| Geometry::parse(data).expect("the checked Fluent icon path"))
            .clone()
    });
    let icon = PathIcon::new();
    icon.set_width(18.0);
    icon.set_height(18.0);
    icon.set_is_hit_test_visible(false);
    AutomationProperties::set_accessibility_view(&icon, AccessibilityView::Raw);
    if name == "chevron_down" {
        icon.set_render_transform(Some(RotateTransform::with_angle(180.0).into()));
    }
    icon.set_data(Some(geometry));
    icon
}

